def pack_context(chunks, budget):
    parts = []
    used = 0
    sep = chr(10) + '---' + chr(10)
    for ch in chunks:
        add = len(ch) if not parts else len(sep) + len(ch)
        if used + add > budget:
            break
        parts.append(ch)
        used += add
    return sep.join(parts)
